functions.template:
{%- set p = http('https://api.awattar.de/v1/marketdata', 900000) -%}
{%- set cur = p.data[0].marketprice -%}
{%- set mn = 999999 -%}{%- set mx = -999999 -%}{%- set mnt = 0 -%}{%- set mxt = 0 -%}
{%- for s in p.data -%}
{%- set v = s.marketprice -%}
{%- if v < mn -%}{%- set mn = v -%}{%- set mnt = (s.start_timestamp / 1000) + 3600 -%}{%- endif -%}
{%- if v > mx -%}{%- set mx = v -%}{%- set mxt = (s.start_timestamp / 1000) + 3600 -%}{%- endif -%}
{%- endfor -%}
{%- set hmn = ((mnt % 86400) / 3600) | int -%}
{%- set mmn = (((mnt % 3600) / 60) | int) -%}
{%- set hmx = ((mxt % 86400) / 3600) | int -%}
{%- set mmx = (((mxt % 3600) / 60) | int) -%}
Strompreis DE (aWATTar): aktuell {{ (cur / 10) | round(1) | replace('.', ',') }} ct/kWh; günstigster Slot {{ hmn }}:{% if mmn < 10 %}0{% endif %}{{ mmn }} Uhr mit {{ (mn / 10) | round(1) | replace('.', ',') }} ct/kWh, teuerster Slot {{ hmx }}:{% if mmx < 10 %}0{% endif %}{{ mmx }} Uhr mit {{ (mx / 10) | round(1) | replace('.', ',') }} ct/kWh.
